INSERT INTO outbox_event(
  id, aggregate_type, aggregate_id, event_type, aggregate_version, payload,
  status, next_attempt_at, attempts, created_at
) VALUES (
  #{id}, #{aggregateType}, #{aggregateId}, #{eventType}, #{aggregateVersion},
  CAST(#{payload} AS JSON), 'NEW', #{now}, 0, #{now}
)

mapper.update:
UPDATE outbox_event
SET status = 'SENT', sent_at = #{now}, lease_until = NULL, owner_token = NULL
WHERE id = #{id} AND status = 'CLAIMED' AND owner_token = #{owner}

UPDATE outbox_event
SET status = 'NEW', next_attempt_at = #{nextAttempt}, lease_until = NULL,
    owner_token = NULL, last_error = #{error}
WHERE id = #{id} AND status = 'CLAIMED' AND owner_token = #{owner}
